function isWrongPrevibankQuote(q){
  if(!q || !Number.isFinite(Number(q.price)))return true;
  const p=Number(q.price),src=String(q.source||'').toLowerCase(),day=q.date||'';
  // 12.141 on 31 August is the Bilanciato Sostenibile NAV, NOT Finanziario.
  if(src.includes('bilanciato'))return true;
  if(day==='2026-08-31' && Math.abs(p-PREVIBANK_BASE.nav)>0.0005)return true;
  // A subsequent quote near 12 or 17 EUR cannot silently replace the 27.646
  // confirmed opening NAV; quarantine it for review rather than valuing it.
  if(day>='2026-08-31' && p<20)return true;
  return false;
}
function cleansePrevibankQuoteHistory(asset){
  if(!asset)return false;
  const existing=Array.isArray(asset.marketQuotes)?asset.marketQuotes:[];
  const invalid=existing.filter(isWrongPrevibankQuote);
  if(invalid.length){
    asset.rejectedQuotes=asset.rejectedQuotes||[];
    for(const q of invalid){
      if(!asset.rejectedQuotes.some(old=>old.date===q.date&&Number(old.price)===Number(q.price))){
        asset.rejectedQuotes.push({...q,reason:'NAV non valido per Previbank Finanziario; verificare comparto'});
      }
    }
    asset.marketQuotes=existing.filter(q=>!isWrongPrevibankQuote(q));
  }else asset.marketQuotes=existing;
  const aug=(asset.marketQuotes||[]).find(q=>q.date===PREVIBANK_BASE.quoteDate);
  if(!aug){
    asset.marketQuotes=insertObservation(asset.marketQuotes,{date:PREVIBANK_BASE.quoteDate,
      price:PREVIBANK_BASE.nav,currency:'EUR',manual:false,verifiedReference:true,
      source:'Previbank ufficiale - Finanziario 31 agosto 2026',checkedAt:null});
  }
  return invalid.length>0 || !aug;
}
