function reconcileLegacyPrevibank(asset){
  if(!asset || !Array.isArray(asset.observations))return false;
  const opening=asset.observations.filter(o=>o.date>=PREVIBANK_BASE.positionDate && o.date<='2026-10-17');
  const hasBase=opening.some(o=>o.date===PREVIBANK_BASE.positionDate&&o.mode==='units'&&
    Math.abs(Number(o.units)-PREVIBANK_BASE.units)<0.0000001);
  const incorrect=opening.some(o=>o.mode!=='units' ||
    Math.abs(Number(o.units)-PREVIBANK_BASE.units)>0.000001 || o.date!==PREVIBANK_BASE.positionDate);
  if(!incorrect && hasBase)return false;
  if(opening.length){
    asset.previousPositions=asset.previousPositions||[];
    // Save only once: do not append the same bad position on every startup.
    if(!asset.previousPositions.some(p=>p.reason==='Rettifica quote dal rendiconto ufficiale 01/09/2026')){
      asset.previousPositions.push({replacedAt:new Date().toISOString(),
        reason:'Rettifica quote dal rendiconto ufficiale 01/09/2026',
        observations:JSON.parse(JSON.stringify(asset.observations))});
    }
  }
  asset.observations=[
    ...asset.observations.filter(o=>o.date<PREVIBANK_BASE.positionDate),
    {date:PREVIBANK_BASE.positionDate,mode:'units',units:PREVIBANK_BASE.units,
      source:'Previbank · posizione ufficiale 01/09/2026'},
    ...asset.observations.filter(o=>o.date>'2026-10-17')
  ];
  asset.previbankBaselineConfirmed=true;
  asset.reconciliationVersion='2.3.3';
  return true;
}

