function quoteFromPrevibank(raw,asset){
  const text=strippedPublicHTML(raw);
  // The index is chronologically ordered. Prefer the most recently published
  // article whose summary actually contains the Finanziario NAV.
  const heading=/Andamento\s+Compart[io][\s\S]{0,160}?\b(gennaio|febbraio|marzo|aprile|maggio|giugno|luglio|agosto|settembre|ottobre|novembre|dicembre)\s+(20\d{2})/gi;
  const candidates=[];let h;
  while((h=heading.exec(text))!==null){
    const date=monthFinalISO(h[1],h[2]);if(!date||date>dNow())continue;
    const portion=text.slice(h.index,Math.min(text.length,h.index+1250));
    const m=portion.match(/Comparto\s*[“"']?\s*Finanziario\b[\s\S]{0,480}?\bvalore\s+(?:della\s+)?quota\s+pari\s+a\s*€?\s*€?\s*(\d{1,4}(?:[.,]\d{1,6})?)/i);
    if(!m)continue;
    const price=parseEuropeanNumber(m[1]);
    if(Number.isFinite(price)&&price>0&&price<500)candidates.push({date,price});
  }
  candidates.sort((a,b)=>b.date.localeCompare(a.date));
  if(!candidates.length)throw Error('Previbank: notizia mensile non leggibile; il prezzo resta invariato');
  const found=candidates[0];
  return packQuote(asset,found.price,found.date,'Previbank · Comparto Finanziario · comunicazione ufficiale mensile', {timeVerified:true,navFrequency:'mensile'});
}

