function quoteFromPrevibank(raw,asset){
  const text=strippedPublicHTML(raw);
  // The public news index contains TWO independent NAVs, Finanziario AND
  // Bilanciato Sostenibile. Extract only the paragraph labelled Finanziario.
  const heading=/Andamento\s+Compart[io][\s\S]{0,160}?\b(gennaio|febbraio|marzo|aprile|maggio|giugno|luglio|agosto|settembre|ottobre|novembre|dicembre)\s+(20\d{2})/gi;
  const matches=[...text.matchAll(heading)];
  const candidates=[];
  for(let i=0;i<matches.length;i++){
    const h=matches[i],date=monthFinalISO(h[1],h[2]);
    if(!date || date>dNow())continue;
    const next=matches[i+1]?.index??text.length;
    const block=text.slice(h.index,Math.min(next,h.index+2200));
    // Must explicitly say "Il Comparto Finanziario": not just mention its
    // name in the title, and NEVER use the subsequent Bilanciato NAV.
    const financial=block.match(/Il\s+Comparto\s*[“”\"'«]?\s*Finanziario\b/i);
    if(!financial)continue;
    const after=block.slice(financial.index+financial[0].length);
    const bilanciato=after.search(/\b(?:Il\s+)?Comparto\s*[“”\"'«]?\s*Bilanciato\b/i);
    const financialOnly=bilanciato>=0?after.slice(0,bilanciato):after.slice(0,800);
    const found=financialOnly.match(/\bvalore\s+della\s+quota\s*(?:pari\s+a|di)\s*€?\s*€?\s*(\d{1,4}(?:[.,]\d{1,6})?)/i);
    if(!found)continue;
    const price=parseEuropeanNumber(found[1]);
    if(!Number.isFinite(price)||price<=0||price>=500)continue;
    if(date>='2026-08-31'&&price<20)continue; // cross-compartment mixup
    candidates.push({date,price});
  }
  candidates.sort((a,b)=>b.date.localeCompare(a.date));
  if(!candidates.length)throw Error('Previbank: nessun NAV del comparto Finanziario identificato; importazione annullata');
  const q=candidates[0];
  return packQuote(asset,q.price,q.date,'Previbank · Comparto Finanziario · sito ufficiale (non Bilanciato)',
    {timeVerified:true,navFrequency:'mensile'});
}

